CREATE TABLE IF NOT EXISTS rsvps (id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), name TEXT NOT NULL, attendance TEXT NOT NULL, guests INTEGER NOT NULL, events JSONB NOT NULL, dietary TEXT NOT NULL DEFAULT '', message TEXT NOT NULL DEFAULT '');
CREATE TABLE IF NOT EXISTS rsvp_rate_limits (key TEXT PRIMARY KEY, window_start TIMESTAMPTZ NOT NULL, attempts INTEGER NOT NULL);
